<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Accessor\TenantLoginProviderUsersEnabledByDefaultAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderUsersEnabledByDefaultAccessor trait.
 *
 * Covers null default, string/VO assignment via withUsersEnabledByDefault,
 * getUsersEnabledByDefault/usersEnabledByDefault accessors, and isUsersEnabledByDefaultChanged with/without original.
 */
class TenantLoginProviderUsersEnabledByDefaultAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withUsersEnabledByDefault creates a new instance with the UsersEnabledByDefault set
     * from a string value, and getUsersEnabledByDefault returns the primitive string.
     */
    public function testWithUsersEnabledByDefaultFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderUsersEnabledByDefaultAccessorUnitTest();

        // Act
        $result = $holder->withUsersEnabledByDefault(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isUsersEnabledByDefault());
    }
    /**
     * Asserts that withusersEnabledByDefault has access to the value object
     * from a string value, and getUsersEnabledByDefault returns the primitive string.
     */
    public function testWithUsersEnabledByDefaultFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderUsersEnabledByDefaultAccessorUnitTest();

        // Act
        $result = $holder->withUsersEnabledByDefault(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->usersEnabledByDefault()->value());
    }
    public function testChangedUsersEnabledByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderUsersEnabledByDefaultAccessorUnitTest()->withUsersEnabledByDefault(true);
        $original = $holder->withUsersEnabledByDefault( true);
        $same = $holder->withUsersEnabledByDefault( true);
        $modified = $holder->withUsersEnabledByDefault(false);

        // Act
        $withSame = $original->isUsersEnabledByDefaultChanged( $same );
        $withDiferent = $original->isUsersEnabledByDefaultChanged( $modified );

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantLoginProviderUsersEnabledByDefaultAccessorUnitTest
{
  use TenantLoginProviderUsersEnabledByDefaultAccessor;
}
